select template_id, tenant_id, flow_name, flow_json, flow_type, creator, create_time, modifier, update_time, status, delete_flag, app_ver_code, industry_Code from vm_flow_template


		AND status = #{status}


		AND delete_flag = #{deleteFlag}


		AND flow_type = #{flowType}


		AND template_id = #{templateId}




		order by create_time asc


		order by create_time desc


		order by update_time asc


		order by update_time desc


		order by update_time desc

SELECT
	GROUP_CONCAT(template_id) AS templateId
FROM
	vm_flow_template_industry_local
WHERE
	delete_flag = 0

		AND app_ver_code = #{param.appVerCode}


		AND industry_code = #{param.industryCode}


	AND local_version = #{param.localVersion}

SELECT GROUP_CONCAT(template_id) AS templateId FROM vm_flow_template_industry WHERE delete_flag = 0
AND app_ver_code = #{param.appVerCode}
AND industry_code = #{param.industryCode}

SELECT id, template_id, warning_source, STATUS, creator, modifier, create_time, update_time, delete_flag, app_ver_code, industry_code FROM vm_flow_template_industry WHERE status = '1' AND delete_flag = 0
AND app_ver_code = #{param.appVerCode}
AND industry_code = #{param.industryCode}

