AND app_ver_code = #{param.appVerCode}
AND industry_code = #{param.industryCode}
AND local_version = #{param.localVersion}

SELECT id, link_id, link_name, role_id, msg_notify_type, leader_flag, sign_flag, rollback_flag, screen_url, pc_url, app_url, time_limit, notify_admin_flag, msg_notify_limit, msg_notify_company, attr_flag, status, delete_flag, create_time, update_time, creator, modifier, app_ver_code, industry_code, data_filter_permiss, custom_admin, time_limit_company, time_start_alram, time_end_alram, voice_alram, time_remind, time_remind_auto, time_remind_number, if_later_remind, later_remind, later_remind_company, time_push_type, time_limit_push, grid_sign_role, user_type, msg_send_time_interval FROM vm_flow_link_industry_config WHERE STATUS = '1'
AND app_ver_code = #{param.appVerCode}
AND industry_code = #{param.industryCode}
AND link_id != '6' and delete_flag='0'

